using var adapter = new LabScriptedAdapter();
using var c = new LabController(adapter);
string a = c.Submit("SetLevel", 40);
string b = c.Submit("SetLevel", 80);
adapter.Emit(new LabCompletion(b, c.Session, "Completed"));
adapter.Emit(new LabCompletion(a, c.Session, "Completed"));
adapter.Emit(new LabCompletion(a, c.Session, "Completed"));
Console.WriteLine(c.Results[a]); // Completed
Console.WriteLine(c.Results[b]); // Completed
Console.WriteLine($"applied={c.Applied} ignored={c.Ignored}"); // 2 1

int observed = 0;
Action<int> callback = value => observed = value;
void InvokeNow(Action<int> done, int value) => done(value);
var queue = new Queue<Action>();
void QueueLater(Action<int> done, int value) => queue.Enqueue(() => done(value));
Console.WriteLine(observed); // 0
InvokeNow(callback, 7);
Console.WriteLine(observed); // 7
QueueLater(callback, 9);
Console.WriteLine(observed); // 7
queue.Dequeue()();
Console.WriteLine(observed); // 9
